using System;using System.IO;using System.Text;using System.Runtime.Serialization.Json;using GlassBoard;
class MotionPresetsTests {
 static int checks;static void Check(bool b,string message){checks++;if(!b)throw new Exception(message);}
 static T Read<T>(string json){using(var s=new MemoryStream(Encoding.UTF8.GetBytes(json)))return (T)new DataContractJsonSerializer(typeof(T)).ReadObject(s);}
 static T Round<T>(T value){using(var s=new MemoryStream()){var j=new DataContractJsonSerializer(typeof(T));j.WriteObject(s,value);s.Position=0;return (T)j.ReadObject(s);}}
 static int Main(){var legacy=Read<Preferences>("{\"Dock\":{\"OpeningAnimation\":true,\"HoverAnimation\":true,\"SpringReveal\":true,\"OpacityPercent\":43},\"BoardPageMotion\":true,\"Apps\":[{\"Name\":\"保留\",\"Path\":\"keep.exe\"}],\"AllDesktopLayer\":true}");legacy.Normalize();Check(MotionPresets.ApplyInitialBaseline(legacy),"first startup applies direct-response baseline");Check(!legacy.Dock.OpenMotion&&!legacy.Dock.HoverMotion&&!legacy.Dock.SpringReveal&&!legacy.BoardPageMotion&&!legacy.ControlCenter.Motion,"every transition group is disabled");Check(legacy.Apps.Count==1&&legacy.Apps[0].Path=="keep.exe"&&legacy.AllDesktopLayer&&legacy.Dock.OpacityPercent==43,"apps/layer/material are retained");legacy=Round(legacy);legacy.Dock.OpeningAnimation=true;legacy.Dock.HoverAnimation=true;Check(!MotionPresets.ApplyInitialBaseline(legacy)&&legacy.Dock.OpenMotion&&legacy.Dock.HoverMotion,"manual re-enable survives following startups");MotionPresets.DisableTransitions(legacy);Check(!legacy.Dock.OpenMotion&&!legacy.Dock.HoverMotion,"one-click preset can be reapplied");Console.WriteLine(checks+" baseline migration/persistence/manual opt-in checks PASS");return 0;}
}
